 svg=svg('A figure with many heads in a fan, like the cosmic Purusha of the Veda',''.join(f'<circle cx="{110+60*math.cos(-math.pi+k*math.pi/8)}" cy="{80+50*math.sin(-math.pi+k*math.pi/8)}" r="10" fill="#3b6fd0" stroke="#111" stroke-width="1.5"/>' for k in range(9))+'<path d="M80 150 q-4 -60 30 -70 q34 10 30 70z" fill="#ffd60a" stroke="#111" stroke-width="2.5"/>'+lab(110,156,'BAHUŚIRĀḤ',9),B),
